  "supportive_card_ids": ["C03","C20","C04","C12","C13","C16","C24","C25","C29","C30"],
  "contradictory_card_ids": ["C26"],
  "prediction_basis_card_ids": ["C03","C20","C04","C16","C24"],
  "claims": [
    {
      "claim": "Bumetanide, a 5-sulfamoyl anthranilic acid sharing the query acid-sulfamoyl core, has absolute oral bioavailability of 95% in cirrhosis patients after 1 mg oral versus IV dosing, and L2 context reports 95 to 100%.",
      "card_ids": ["C03","C20","C24"]
    },
    {
      "claim": "The closest structural analog azosemide has L1 absolute oral bioavailability of 20.4% in fasted healthy humans, meeting the F >= 20% threshold; the L2 urinary-recovery estimate of 10% is indirect and does not overturn the L1 gold value.",
      "card_ids": ["C04","C26"]
    },
    {
      "claim": "Cirrhosis-condition contexts consistently show high oral bioavailability: metoclopramide 79 to 82% (L1) and 82% versus 60% control (L2), tolfenamic acid 91 to 100% (L1) and 113 to 126% (L2).",
      "card_ids": ["C12","C13","C16","C25","C29","C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C23","C24","C25","C26","C27","C28","C29","C30","C31"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "Azosemide, the closest structural analog, has conflicting estimates (20.4% L1 absolute versus 10% L2 urinary recovery) and was studied in fasted healthy subjects rather than cirrhosis patients.",
    "The query furan and carboxylic acid substituents may alter first-pass metabolism and transporter handling relative to azosemide and bumetanide.",
    "Cirrhosis effects on the query specific metabolic and transporter pathways are not directly measured."
  ],
  "decision_summary": "L2 evidence is mixed but net supportive. The closest analog azosemide has an L2 urinary-recovery estimate of 10%, below threshold, but the L1 absolute value is 20.4% and the estimate is indirect and from healthy fasted subjects. Cirrhosis-condition evidence is reinforced by L2 records: bumetanide 95 to 100%, tolfenamic acid 113 to 126%, metoclopramide 82% versus 60% control. The query is a sulfamoyl anthranilic acid like bumetanide, which has 95% F in cirrhosis. Condition-matched evidence supports F >= 20%. Prediction remains high with moderate confidence."
}

